fn prime_num(n: u64) -> bool {
    // We assume n >= 2 as per the problem statement.
    // Handle the small cases directly.
    if n <= 3 {
        return true;
    }
    // Eliminate even numbers greater than 2.
    if n % 2 == 0 {
        return false;
    }

    // Only odd divisors need to be checked now.
    // We only need to search up to sqrt(n), but avoid floating‐point by using k*k.
    let mut k = 3;
    while k * k <= n {
        if n % k == 0 {
            return false;
        }
        k += 2;
    }
    true
}

